// Waypoints' colours. The four palettes below are COPIED from agent-pulse/hooks/palette.ts
// (each mod is installed alone, so there is no import across mods): keep the values in
// step with Agent-Pulse. palette.test.ts pins a few, so a drift is a deliberate edit.
// Only the phases Waypoints paints with are copied: idle, tool, agent, approval.

const CLAUDE_HEX = { idle: '#8a8a8a', tool: '#d97757', agent: '#2ec4b6', approval: '#ffc107' }
const EMBER_HEX = { idle: '#857a74', tool: '#d97757', agent: '#8cc7b5', approval: '#ffcf5c' }
const EMBER_GLOW = { idle: '#9a8f88', tool: '#f3a97c', agent: '#b6d99a', approval: '#ffb347' }
const NEON_HEX = { idle: '#5b6785', tool: '#22e5f0', agent: '#4ade80', approval: '#ffd166' }
const NEON_GLOW = { idle: '#6f7a99', tool: '#6ef0c8', agent: '#bef264', approval: '#ff9f6e' }
const MONO_HEX = { idle: '#7a7a7a', tool: '#d0d0d0', agent: '#d0d0d0', approval: '#ffc107' }

const OUTCOME_HEX = { ok: '#4eba65', error: '#ff6b80', denied: '#ffc107', interrupted: '#8a8a8a' }
const OUTCOME_THEME = { ok: 'success', error: 'error', denied: 'warning', interrupted: 'inactive' }
const EMBER_OUTCOME = { ok: '#8fd694', error: '#ff6b6b', denied: '#ffcf5c', interrupted: '#857a74' }
const NEON_OUTCOME = { ok: '#4ade80', error: '#ff5c7a', denied: '#ffd166', interrupted: '#6f7a99' }

const SHIMMER_STEPS = 12

// phase: what Text takes (a theme key where one means the same); hex/glow: the same colour as hex
const PALETTES = {
  ember: {
    phase: EMBER_HEX,
    hex: EMBER_HEX,
    glow: EMBER_GLOW,
    outcome: EMBER_OUTCOME,
    sparkle: ['#d97757', '#e8957a', '#f3a97c', '#f6c177', '#ffe3b0', '#f6c177', '#f3a97c', '#e8957a'],
    heat: ['#f6d36b', '#ff9a4d', '#ff5c5c'],
    agents: ['#8cc7b5', '#f2b8a0', '#c6a4ec', '#f6c177', '#ee9aa4', '#9fc7e8'],
  },
  claude: {
    phase: { idle: 'inactive', tool: 'claude', agent: CLAUDE_HEX.agent, approval: 'warning' },
    hex: CLAUDE_HEX,
    glow: CLAUDE_HEX,
    outcome: OUTCOME_THEME,
    sparkle: ['#d97757', '#e48a66', '#f0a47f', '#fbc8a8', '#ffe6d5', '#fbc8a8', '#f0a47f', '#e48a66'],
    heat: ['#e0af68', '#ff9e64', 'error'],
    agents: ['#2ec4b6', '#f4a261', '#a78bfa', '#60a5fa', '#f472b6', '#84cc16'],
  },
  neon: {
    phase: NEON_HEX,
    hex: NEON_HEX,
    glow: NEON_GLOW,
    outcome: NEON_OUTCOME,
    sparkle: ['#22e5f0', '#5eead4', '#7dd3fc', '#b39dff', '#ff8ad8', '#c4a1ff', '#7aa2ff', '#38bdf8'],
    heat: ['#ffd166', '#ff9f6e', '#ff5c7a'],
    agents: ['#5eead4', '#ff8ad8', '#bef264', '#ffd166', '#b39dff', '#7dd3fc'],
  },
  mono: {
    phase: { idle: 'inactive', tool: 'text', agent: 'text', approval: 'warning' },
    hex: MONO_HEX,
    glow: MONO_HEX,
    outcome: OUTCOME_THEME,
    sparkle: ['#6e6e6e', '#8a8a8a', '#a8a8a8', '#c8c8c8', '#e8e8e8', '#c8c8c8', '#a8a8a8', '#8a8a8a'],
    heat: ['warning', 'warning', 'error'],
    agents: ['#d0d0d0', '#a8a8a8', '#e8e8e8', '#8a8a8a'],
  },
}

export const PALETTE_NAMES = ['ember', 'claude', 'neon', 'mono']
export const LEVELS = ['off', 'subtle', 'full']

export function paletteOf(name) {
  return PALETTES[name === 'claude' || name === 'neon' || name === 'mono' ? name : 'ember']
}

export function levelOf(value) {
  return value === 'off' || value === 'full' ? value : 'subtle'
}

// Mixes two hex colours, t 0 being a and 1 being b
export function mix(a, b, t) {
  const channels = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16))
  const from = channels(a)
  const to = channels(b)
  const k = Math.min(1, Math.max(0, t))
  return '#' + from.map((c, i) => Math.round(c + (to[i] - c) * k).toString(16).padStart(2, '0')).join('')
}

// A phase's colour t of the way from its core to its glow. A flat palette keeps its own
// colour, which may be a theme key.
export function shadeOf(palette, phase, t) {
  const core = palette.hex[phase]
  const glow = palette.glow[phase]
  return core === glow ? palette.phase[phase] : mix(core, glow, t)
}

// The spinner's colours, one per frame: core to glow and back, or the one colour of a flat palette
export function shimmerOf(palette, phase) {
  if (palette.hex[phase] === palette.glow[phase]) return [palette.phase[phase]]
  return Array.from({ length: SHIMMER_STEPS }, (_, i) => shadeOf(palette, phase, (1 - Math.cos((i / SHIMMER_STEPS) * 2 * Math.PI)) / 2))
}

// One colour per agent, the same each time its name comes up (and the same Agent-Pulse gives it)
export function agentColorOf(palette, name) {
  let hash = 0
  for (const char of String(name)) hash = (hash * 31 + char.charCodeAt(0)) | 0
  return palette.agents[Math.abs(hash) % palette.agents.length] || palette.hex.agent
}

// The roles Waypoints draws with, mapped onto the palette's phase colours so a palette
// means the same in both mods. `done(t)` shades along the route, t 0..1 (position / width).
export function rolesOf(name) {
  const p = paletteOf(name)
  return {
    name: PALETTE_NAMES.includes(name) ? name : 'ember',
    done: (t) => shadeOf(p, 'tool', t),
    active: shimmerOf(p, 'tool'),
    activeStill: p.phase.tool,
    pending: p.phase.idle,
    attention: p.phase.approval,
    ok: p.outcome.ok,
    sparkle: p.sparkle,
    heat: p.heat[0],
    agent: (by) => agentColorOf(p, by),
    // the SVG always takes hex, never a theme key
    hex: { done: p.hex.tool, glow: p.glow.tool, pending: p.hex.idle, ok: p.hex.tool, sparkle: p.sparkle },
  }
}

// The row Waypoints follows in /config; the key is confirmed live (see DESIGN.md)
export const FOLLOW_KEYS = { palette: 'agent-pulse.palette', animation: 'agent-pulse.animation' }

// The look to draw with. options: the userConfig values ('follow' or explicit); rows:
// $.config.list(). 'follow' takes Agent-Pulse's own value, or ember/subtle without it.
export function resolveLook(options, rows) {
  const o = options || {}
  const list = Array.isArray(rows) ? rows : []
  const fromRow = (key) => {
    const row = list.find((r) => r && r.key === key)
    return row ? row.value : undefined
  }
  const palette = o.palette && o.palette !== 'follow' ? o.palette : fromRow(FOLLOW_KEYS.palette)
  const animation = o.animation && o.animation !== 'follow' ? o.animation : fromRow(FOLLOW_KEYS.animation)
  const name = PALETTE_NAMES.includes(palette) ? palette : 'ember'
  return { palette: name, level: levelOf(animation) }
}

files.hooks/draw.mjs:
// Waypoints' drawing: the band above the prompt (and, below, the pane). Pure: every
// function takes the element table `el` and a `view` and returns a tree, so the harness
// can draw a band without the engine.
//
// view = {
//   g,        the goal                     now,    the clock
//   mask,     Recording Mode's masker      roles,  rolesOf(palette)
//   level,    'off' | 'subtle' | 'full'    width,  bodyColumns
//   maxRows,  rows the band may take       nudged, Claude was reminded to plan
//   pulse,    (key, props, width) → a terminal Client (built in register.mjs, which the
//             engine reads the module path from); absent, nothing animates
//   open,     () → open the pane
//   svg,      the surface paints Svg (Desktop, mobile): the engine's `e.surface` says so, as
//             the terminal's element table lists `Svg` too and cannot tell them apart
// }
// A surface that paints Svg gets the route as one Svg and a still spinner; the terminal
// gets Text runs and the Client animations.

import { minutes, clock, clip, basename } from './fmt.mjs'
import { progress, eta, live, weight } from './plan.mjs'
import { routeCells, miniRoute, runs } from './route.mjs'
import { routeSvg, routeAlt, svgWidth } from './svg.mjs'
import { NOTE_AT } from './prune.mjs'

export const FULL_MS = 8000 // a finished band keeps all its rows this long
export const SPIN = { frames: ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'], ms: 80 }

// ---------- words ----------

export function label(g) {
  return g.kind === 'plan' ? 'Plan' : 'Goal'
}

export function isPaused(g) {
  return g.status === 'running' && !g.active && g.lastTurnEnd > 0
}

// A task running past twice the plan's own pace for its size (only once the ETA exists)
export function runsLong(g, t, now) {
  if (!eta(g, now)) return false
  const pace = (now - (g.planAt || g.startedAt)) / progress(g).doneW
  return now - t.startedAt > 2 * pace * weight(t)
}

function byOf(t) {
  return t.by && t.by !== 'main' ? t.by : ''
}

function lastDone(tasks) {
  return tasks.filter((t) => t.status === 'done').sort((a, b) => b.doneAt - a.doneAt || b.id - a.id)[0]
}

// ---------- the route ----------

function colorOf(roles, cell) {
  if (cell.role === 'done') return roles.done(cell.t)
  if (cell.role === 'sparkle') return roles.sparkle[0]
  if (cell.role === 'active') return roles.activeStill
  return roles.pending
}

function routeRow(el, v, cells, tail, tasks) {
  const { Box, Text } = el
  const finishing = v.g.status === 'met'
  // Desktop draws the route as an Svg, which moves by CSS; only the terminal takes a Client
  const svg = v.svg && el.Svg
  const animate = v.pulse && !svg
  const kids = []
  if (svg) {
    const p = progress(v.g)
    const running = tasks.map((t, i) => (t.status === 'active' ? i + 1 : 0)).filter(Boolean)
    const width = svgWidth(v.width)
    const source = routeSvg(cells, { hex: v.roles.hex, level: v.level, width, finishId: finishing ? `${v.g.startedAt}-${v.g.endedAt}` : '' })
    kids.push(el.Svg({ key: 'route', source, alt: routeAlt(p.doneN, p.n, running), width, height: 14 }))
  } else if (finishing && v.level === 'full' && animate) {
    // one-shot, keyed by the finish: it sweeps the sparkle colours along the route once,
    // then rests on the solid route
    kids.push(
      v.pulse(
        `sweep-${v.g.startedAt}-${v.g.endedAt}`,
        { kind: 'sweep', chars: cells.map((c) => c.ch).join(''), done: cells.map((c) => colorOf(v.roles, c)), colors: [...v.roles.sparkle] },
        cells.length,
      ),
    )
  } else {
    let buf = []
    const flush = () => {
      for (const r of runs(buf, (c) => colorOf(v.roles, c))) kids.push(Text({ color: r.color, children: [r.text] }))
      buf = []
    }
    for (const c of cells) {
      if (c.role === 'active' && v.level !== 'off' && animate) {
        flush()
        kids.push(v.pulse(`node-${c.id}`, { kind: 'node', colors: [...v.roles.active], breathe: v.level === 'full' }, 1))
      } else buf.push(c)
    }
    flush()
  }
  if (tail) kids.push(Text({ dimColor: true, children: [tail] }))
  return Box({ flexDirection: 'row', children: kids })
}

// ---------- rows ----------

function headerRow(el, v, mark, right) {
  const { Box, Text, Button } = el
  const { g, mask } = v
  const open = Button({ key: 'goal-tasks', label: 'all tasks', hotkey: 'g', plain: true, onPress: () => v.open && v.open() })
  return Box({
    flexDirection: 'row',
    justifyContent: 'space-between',
    width: '100%',
    columnGap: 2,
    children: [
      Box({
        flexDirection: 'row',
        flexShrink: 1,
        children: [mark, Text({ bold: true, wrap: 'truncate-end', children: [`${label(g)}: ${mask(g.title)}`] })],
      }),
      Box({ flexDirection: 'row', columnGap: 2, flexShrink: 0, children: [...right, open] }),
    ],
  })
}

function spinner(el, v, key) {
  if (v.level === 'off' || v.svg || !v.pulse) return el.Text({ color: v.roles.activeStill, children: ['◉'] })
  return v.pulse(key, { kind: 'spin', frames: SPIN.frames, ms: SPIN.ms, colors: [...v.roles.active] }, 1)
}

function nowRow(el, v, t, more) {
  const { Box, Text } = el
  const { g, now, mask, roles } = v
  const by = byOf(t)
  const long = runsLong(g, t, now)
  const right = []
  if (by) right.push(Text({ color: roles.agent(by), children: [`◆ ${clip(mask(by), 20)}`] }))
  right.push(Text(long ? { color: roles.heat, children: [` · ${minutes(now - t.startedAt)}`] } : { dimColor: true, children: [` · ${minutes(now - t.startedAt)}`] }))
  if (more) right.push(Text({ dimColor: true, children: [`  +${more} running`] }))
  return Box({
    flexDirection: 'row',
    justifyContent: 'space-between',
    width: '100%',
    columnGap: 2,
    children: [
      Box({ flexDirection: 'row', flexShrink: 1, columnGap: 1, children: [spinner(el, v, `spin-${t.id}`), Text({ bold: true, wrap: 'truncate-end', children: [`${t.size}  ${mask(t.title)}`] })] }),
      Box({ flexDirection: 'row', flexShrink: 0, children: right }),
    ],
  })
}

function doneRow(el, v, t) {
  const took = t.doneAt > t.startedAt ? minutes(t.doneAt - t.startedAt) : ''
  return el.Text({ dimColor: true, wrap: 'truncate-end', children: [`✓ ${t.size}  ${v.mask(t.title)}${took ? '  ' + took : ''}`] })
}

function nextRow(el, v, t) {
  return el.Text({ dimColor: true, wrap: 'truncate-end', children: [`  next ○ ${t.size}  ${v.mask(t.title)}`] })
}

function notableRow(el, v) {
  const { g, mask, roles } = v
  if (g.check && g.check.met === false && g.check.reason) {
    return el.Text({ color: roles.attention, wrap: 'truncate-end', children: [`Goal check: not met yet: ${mask(g.check.reason)}`] })
  }
  if (g.interrupted) return el.Text({ color: roles.attention, children: ['interrupted'] })
  if (isPaused(g) && progress(g).doneN < progress(g).n) return el.Text({ color: roles.attention, children: ['⏸ paused, waiting on you'] })
  return null
}

// ---------- the band ----------

export function drawBand(el, v) {
  const { Box, Text } = el
  const { g, now, roles } = v
  const p = progress(g)
  const mark = Text({ color: roles.activeStill, children: ['◎ '] })

  if (g.status === 'running' && !g.planAt) {
    const wait = Text({ dimColor: true, wrap: 'truncate-end', children: [v.nudged ? 'No plan yet: reminded Claude to plan with Waypoints' : "Waiting for Claude's task plan…"] })
    return Box({
      flexDirection: 'column',
      children: [headerRow(el, v, mark, [Text({ dimColor: true, children: ['planning…'] })]), Box({ flexDirection: 'row', columnGap: 1, children: [spinner(el, v, 'spin-plan'), wait] })],
    })
  }

  if (g.status !== 'running') {
    const finished = g.status === 'met'
    if (!finished) return Box({ flexDirection: 'column', children: [headerRow(el, v, mark, [Text({ dimColor: true, children: ['stopped'] })])] })
    if (now - g.endedAt >= FULL_MS) {
      const ok = Text({ color: roles.ok, children: ['✓ '] })
      const took = minutes((g.endedAt || now) - g.startedAt)
      return Box({ flexDirection: 'column', children: [headerRow(el, v, ok, [Text({ dimColor: true, children: [`${p.n} tasks · done in ${took}`] })])] })
    }
  }

  const tasks = live(g).sort((a, b) => a.id - b.id)
  const right = []
  if (g.status === 'met') {
    right.push(Text({ color: roles.ok, bold: true, children: [`done ✓ in ${minutes((g.endedAt || now) - g.startedAt)}`] }))
  } else {
    const t = eta(g, now)
    right.push(Text({ children: [Text({ color: roles.activeStill, bold: true, children: [`${p.doneN} of ${p.n} · ${p.pct}%`] }), t ? Text({ dimColor: true, children: [` · ~${minutes(t.ms)}`] }) : null].filter(Boolean) }))
  }
  const head = headerRow(el, v, mark, right)

  // the route fills the width, less the dim +k when the plan grew
  const grew = g.firstPlan && p.n > g.firstPlan ? ` +${p.n - g.firstPlan}` : ''
  const room = Math.max(8, v.width - grew.length)
  const { cells } = routeCells(tasks, room, { finished: g.status === 'met' })
  const parts = { head: [head, routeRow(el, v, cells, grew, tasks)], now: [], next: [], note: [] }

  const active = tasks.filter((t) => t.status === 'active')
  if (active.length) {
    active.slice(0, 2).forEach((t, i) => parts.now.push(nowRow(el, v, t, i === 1 ? Math.max(0, active.length - 2) : 0)))
  } else {
    const last = lastDone(tasks)
    if (last) parts.now.push(doneRow(el, v, last))
  }
  const pending = tasks.find((t) => t.status === 'pending')
  if (pending && g.status === 'running') parts.next.push(nextRow(el, v, pending))
  const note = g.status === 'running' ? notableRow(el, v) : null
  if (note) parts.note.push(note)

  // short of room, the rows give way in this order: next, notable, now
  const max = v.maxRows > 0 ? v.maxRows : Infinity
  let total = parts.head.length + parts.now.length + parts.next.length + parts.note.length
  for (const k of ['next', 'note', 'now']) {
    while (total > max && parts[k].length) {
      parts[k].pop()
      total -= 1
    }
  }
  return Box({ flexDirection: 'column', children: [...parts.head, ...parts.now, ...parts.next, ...parts.note] })
}

// ---------- the pane ----------

const BAR_CELLS = 12 // the longest finished task's duration bar
const NO_CONNECTORS_OVER = 10 // tasks; past this the trail is rows alone

// 30s, 4m, 1h05m: short enough for a column
export function short(ms) {
  const s = Math.max(0, Math.round((Number(ms) || 0) / 1000))
  return s < 60 ? s + 's' : minutes(s * 1000)
}

// The line under the pane's title: the numbers, elapsed, the ETA, growth, goal checks
export function statsLine(g, p, now) {
  if (g.status === 'met') return `done ✓ in ${minutes((g.endedAt || now) - g.startedAt)}`
  if (g.status !== 'running') return 'stopped'
  if (!g.planAt) return 'planning…'
  const parts = [`${p.doneN} of ${p.n} · ${p.pct}%`, `${minutes(now - g.startedAt)} elapsed`]
  const t = eta(g, now)
  if (t) parts.push(`~${minutes(t.ms)} left (≈${clock(t.at)})`)
  else if (p.doneN < 2) parts.push('ETA after 2 tasks finish')
  if (g.firstPlan && p.n > g.firstPlan) parts.push(`plan grew ${g.firstPlan} → ${p.n}`)
  if (g.checks) parts.push(`${g.checks} goal check${g.checks === 1 ? '' : 's'}`)
  return parts.join(' · ')
}

function trailRow(el, v, t, i, count, barOf, titleW) {
  const { Box, Text } = el
  const { now, mask, roles } = v
  const last = i === count - 1
  const glyph = t.status === 'dropped' ? '×' : t.status === 'active' ? '◉' : last ? '◎' : t.status === 'done' ? '●' : '○'
  const color = t.status === 'done' ? roles.done(count > 1 ? i / (count - 1) : 0) : t.status === 'active' ? roles.activeStill : roles.pending
  const title = clip(mask(t.title), titleW - 3)
  const body =
    t.status === 'dropped'
      ? Text({ dimColor: true, strikethrough: true, children: [`${t.size}  ${title}`] })
      : Text({ bold: t.status === 'active', dimColor: t.status === 'pending', children: [`${t.size}  ${title}`] })
  const tail = []
  if (t.status === 'done') {
    const dur = t.doneAt - t.startedAt
    if (dur > 0) tail.push(Text({ color: roles.done(count > 1 ? i / (count - 1) : 0), children: ['▅'.repeat(barOf(dur))] }), Text({ dimColor: true, children: [' ' + short(dur)] }))
  } else if (t.status === 'active') {
    const by = byOf(t)
    if (by) tail.push(Text({ color: roles.agent(by), children: [`◆ ${clip(mask(by), 20)}`] }), Text({ dimColor: true, children: [' · '] }))
    tail.push(Text({ color: runsLong(v.g, t, now) ? roles.heat : undefined, dimColor: !runsLong(v.g, t, now), children: [`running ${short(now - t.startedAt)}`] }))
  } else if (t.status === 'dropped') {
    tail.push(Text({ dimColor: true, children: [t.note ? `dropped: ${mask(t.note)}` : 'dropped'] }))
  }
  // the tail is one Text, so its pieces sit side by side with no column gap between them
  return Box({ flexDirection: 'row', columnGap: 1, children: [Text({ color, children: [glyph] }), Box({ width: titleW, flexShrink: 0, children: [body] }), ...(tail.length ? [Text({ children: tail })] : [])] })
}

function connectorRow(el, v, above) {
  return above.status === 'done' ? el.Text({ color: v.roles.done(0.5), children: ['┃'] }) : el.Text({ dimColor: true, children: ['┆'] })
}

function otherRow(el, v, g) {
  const { Box, Text } = el
  const { now, mask, roles } = v
  const p = progress(g)
  const name = clip(mask(`${g.label || basename(g.cwd)}: ${g.title}`), Math.max(16, Math.floor(v.width * 0.35)))
  let tail
  if (g.status === 'met') tail = 'done ✓'
  else if (g.status !== 'running') tail = 'stopped'
  else if (!g.planAt) tail = 'planning'
  else {
    const t = eta(g, now)
    tail = `${p.pct}% · ${t ? '~' + minutes(t.ms) : p.doneN + '/' + p.n}`
  }
  const { cells } = miniRoute(g)
  const route = runs(cells, (c) => colorOf(roles, c)).map((r) => Text({ color: r.color, children: [r.text] }))
  return Box({
    flexDirection: 'row',
    columnGap: 2,
    children: [Text({ wrap: 'truncate-end', children: [name] }), Box({ flexDirection: 'row', children: route }), Text(g.status === 'met' ? { color: roles.ok, children: [tail] } : { dimColor: true, children: [tail] })],
  })
}

// view adds: others (the other chats' goals), sessionId, commandName, settings
export function drawPane(el, v) {
  const { Box, Text } = el
  const { g, mask, roles } = v
  const rows = []
  if (g) {
    const p = progress(g)
    rows.push(Text({ bold: true, wrap: 'truncate-end', children: [`◎ ${label(g)}: ${mask(g.title)}`] }))
    rows.push(Text({ dimColor: true, wrap: 'truncate-end', children: ['  ' + statsLine(g, p, v.now)] }))
    rows.push(Text({ children: [' '] }))
    const tasks = g.tasks.filter((t) => !t.replaced)
    if (!tasks.length) rows.push(Text({ dimColor: true, children: ['No task plan yet.'] }))
    const longest = Math.max(1, ...tasks.filter((t) => t.status === 'done').map((t) => t.doneAt - t.startedAt))
    const barOf = (dur) => Math.max(1, Math.round((BAR_CELLS * dur) / longest))
    const titleW = Math.max(16, Math.min(48, v.width - 34))
    tasks.forEach((t, i) => {
      rows.push(trailRow(el, v, t, i, tasks.length, barOf, titleW))
      if (i < tasks.length - 1 && tasks.length <= NO_CONNECTORS_OVER) rows.push(connectorRow(el, v, t))
    })
    if (g.check && g.check.reason) {
      rows.push(Text({ children: [' '] }))
      rows.push(Text(g.check.met === false ? { color: roles.attention, children: [`Last goal check: not met yet: ${mask(g.check.reason)}`] } : { dimColor: true, children: [`Last goal check: ${mask(g.check.reason)}`] }))
    }
  } else {
    rows.push(Text({ dimColor: true, children: ['No goal in this chat. Type /goal <what done looks like> to start one.'] }))
  }
  const rest = (v.others || []).filter((o) => o.sessionId !== v.sessionId)
  rows.push(Text({ children: [' '] }))
  rows.push(Text({ bold: true, children: [`Other chats (${rest.length})`] }))
  if (!rest.length) rows.push(Text({ dimColor: true, children: ['No other chat has a goal in the last hour.'] }))
  for (const o of rest.slice(0, 15)) rows.push(otherRow(el, v, o))
  rows.push(Text({ children: [' '] }))
  const s = v.settings || {}
  const c = v.commandName || 'waypoints'
  const f = v.files
  if (f && f.count > NOTE_AT) rows.push(Text({ dimColor: true, children: [`${f.count} old files in ${f.dir} · /${c} prune, or delete them while no plan is running`] }))
  rows.push(Text({ dimColor: true, children: [`auto: ${s.auto ? 'on' : 'off'} · /${c} hide|show · clear (stop the goal) · look & pane: /config → Waypoints`] }))
  return Box({ flexDirection: 'column', children: rows })
}

files.hooks/pane.mjs:
// When the pane opens and closes by itself. Pure bookkeeping, no engine calls, so the rules
// the design lists (a person's close sticks, an unload's does not) can be tested: the test
// engine cannot raise a ui.close with an origin.
//
// - It opens on a goal's first plan, unless the setting is off, the person closed the pane
//   during this goal, or it is open already.
// - A pane the mod opened is the mod's until the person opens it themselves; the mod closes
//   only its own, once the band has gone.

export function createAutoPane() {
  const closedGoals = new Set() // startedAt of each goal whose pane the person closed
  let owned = false // the mod opened the pane and the person has not taken it over

  return {
    canOpen: (mode, goal, isOpen) => mode !== 'off' && !!goal && !isOpen && !closedGoals.has(goal.startedAt),
    // the mod opened it
    opened: () => {
      owned = true
    },
    // the person asked for it (/waypoints, g): theirs from now on
    takenOver: () => {
      owned = false
    },
    // ui.close arrived: only the person's own close is remembered; a plugin's call or the
    // engine dropping the pane (unload) is not a decision about this goal
    closed: (origin, goal) => {
      owned = false
      if (origin && origin.kind === 'person' && goal) closedGoals.add(goal.startedAt)
    },
    // the band has gone: the mod takes back a pane it opened
    shouldClose: (isOpen, bandUp) => owned && isOpen && !bandUp,
    owns: () => owned,
  }
}

files.hooks/prune.mjs:
// The data folder's upkeep: which chats' files the pane lists, when it says the folder has
// grown, what /waypoints prune deletes and the delete it runs, and how the folder is named
// to the person. Pure, so the rules are tested without the engine.

export const OTHERS_MS = 3600000 // other chats' goals shown in /waypoints
export const NOTE_AT = 100 // past this many files the pane names the folder

export const DEAD_MS = 24 * 3600000 // restore() never loads a file this old again
export const PRUNE_MAX = 200 // files one /waypoints prune deletes at most

// The file names /waypoints prune deletes, oldest first. items: { name, mtimeMs, goal },
// goal null for a file that did not parse. Never this chat's file; never a running goal
// touched within DEAD_MS. A file that did not parse is kept for OTHERS_MS, as another chat
// may be writing it right now.
export function pickPrunable(items, { now, self }) {
  const old = (ms) => now - (ms || 0) > OTHERS_MS
  return items
    .filter((it) => {
      if (it.name === self) return false
      if (now - (it.mtimeMs || 0) > DEAD_MS) return true
      if (!it.goal) return old(it.mtimeMs)
      return it.goal.status !== 'running' && old(it.goal.endedAt || it.mtimeMs)
    })
    .sort((a, b) => (a.mtimeMs || 0) - (b.mtimeMs || 0))
    .slice(0, PRUNE_MAX)
    .map((it) => it.name)
}

// What cmd would read as syntax rather than as a path
const CMD_META = /[&|<>^%!"]/

// The host's delete as an argv, no shell: each path is its own argument. On Windows `del`
// lives in cmd, which parses the line again, so a path holding a cmd metacharacter deletes
// nothing (null) and the person is sent to the folder instead.
export function deleteArgv(win, paths) {
  if (!win) return ['rm', '-f', '--', ...paths]
  if (paths.some((p) => CMD_META.test(p))) return null
  return ['cmd', '/d', '/c', 'del', '/f', '/q', ...paths.map((p) => p.replace(/\//g, '\\'))]
}

// The folder as the person's system writes it, ending in a separator: a Windows home
// (with a `\`) turns every `/` into `\`
export function shownPath(path) {
  const p = String(path || '')
  return p.includes('\\') ? p.replace(/\//g, '\\') + '\\' : p + '/'
}

files.hooks/pulse.mjs:
// The terminal's animations, one `Client` region each, all a fixed width so the band's
// layout never moves under them. Each runs on the surface's frame clock; the hooks never
// run per frame. A new key (a new task, a new finish) is a new instance with its own clock.
//
// - spin:  the running task's spinner, cycling `frames` every `ms`, with `colors` alongside
// - node:  the pulsing node at the start of a running leg: it cycles `colors`, and with
//          `breathe` also swells ◉ → ◎ → ◉
// - sweep: the finish, played once: the sparkle `colors` run along the route (`chars`), then
//          it rests on the solid route in the `done` colours (one per char)

const NODE_MS = 120
const SWEEP_MS = 60
const SWEEP_FRAMES = 25 // 1.5 s
const TAIL = 4 // cells the sparkle trails behind the head

export default function Pulse(props, surface) {
  const { Text } = surface.elements

  if (surface.state === undefined) {
    let frame = 0
    const ms = props.kind === 'spin' ? props.ms : props.kind === 'node' ? NODE_MS : SWEEP_MS
    const stop = surface.every(ms, () => {
      frame += 1
      // the sweep plays once, then rests
      if (props.kind === 'sweep' && frame >= SWEEP_FRAMES) stop()
      surface.setState({ frame })
    })
  }

  const frame = surface.state ? surface.state.frame : 0

  if (props.kind === 'spin') {
    return Text({ color: props.colors[frame % props.colors.length], children: [props.frames[frame % props.frames.length] || ' '] })
  }

  if (props.kind === 'node') {
    const glyph = props.breathe && Math.floor(frame / 3) % 2 === 1 ? '◎' : '◉'
    return Text({ color: props.colors[frame % props.colors.length], children: [glyph] })
  }

  // sweep: the head runs from the start to past the end; behind it the sparkle, ahead of it the route
  const chars = [...props.chars]
  const head = Math.round((frame / SWEEP_FRAMES) * (chars.length + TAIL))
  const n = props.colors.length
  const cells = chars.map((ch, i) => ({ ch, color: frame < SWEEP_FRAMES && i <= head && i > head - TAIL ? props.colors[(i + frame) % n] : props.done[i] }))
  const runs = []
  for (const c of cells) {
    const last = runs[runs.length - 1]
    if (last && last.color === c.color) last.text += c.ch
    else runs.push({ text: c.ch, color: c.color })
  }
  return Text({ children: runs.map((r) => Text({ color: r.color, children: [r.text] })) })
}

files.hooks/route.mjs:
// The route: the plan drawn as a line of nodes and legs. Pure: it returns cells
// { ch, role, t } and knows nothing of colour or the engine; draw.mjs colours them
// and svg.mjs draws the same cells as a picture. Roles: 'done', 'active' (the pulsing
// node), 'pending' (dim, the running leg included) and 'sparkle' (the finish mark).

import { weight } from './plan.mjs'

const MAX_UNIT = 6 // cells per unit of work when there is room to spare

function route(tasks) {
  return tasks.filter((t) => t.status !== 'dropped' && !t.replaced).sort((a, b) => a.id - b.id)
}

function cell(ch, role) {
  return { ch, role, t: 0 }
}

// Cells for a route whose legs are already measured. legs[i] is the length of task i's leg.
function layout(tasks, legs, finished) {
  const cells = []
  // node k is the start of task k (the end of task k-1); a running task lights its start node
  const lit = (k) => tasks[k] && tasks[k].status === 'active'
  for (let k = 0; k <= tasks.length; k++) {
    const last = k === tasks.length
    if (finished) cells.push(last ? cell('✦', 'sparkle') : cell('●', 'done'))
    else if (lit(k)) cells.push({ ...cell('◉', 'active'), id: tasks[k].id })
    else if (last) cells.push(cell('◎', tasks[k - 1].status === 'done' ? 'done' : 'pending'))
    else if (k === 0 || tasks[k - 1].status === 'done') cells.push(cell('●', 'done'))
    else cells.push(cell('○', 'pending'))
    if (last) break
    const done = finished || tasks[k].status === 'done'
    for (let i = 0; i < legs[k]; i++) cells.push(done ? cell('━', 'done') : cell('┄', 'pending'))
  }
  const span = Math.max(1, cells.length - 1)
  cells.forEach((c, i) => (c.t = i / span))
  return cells
}

// One glyph per task, no legs, cut with … when the plan is longer than the room
function dense(tasks, width, finished) {
  const glyph = (t) => (finished || t.status === 'done' ? cell('●', 'done') : t.status === 'active' ? { ...cell('◉', 'active'), id: t.id } : cell('○', 'pending'))
  let cells = tasks.map(glyph)
  if (cells.length > width) cells = [...cells.slice(0, Math.max(0, width - 1)), cell('…', 'pending')]
  const span = Math.max(1, cells.length - 1)
  cells.forEach((c, i) => (c.t = i / span))
  return cells
}

// The band's route, fitted to `width` cells: legs proportional to S/M/L (at least 2 cells),
// then 1 cell each, then dense. `finished` draws it all solid with a ✦ at the end.
export function routeCells(allTasks, width, { finished = false } = {}) {
  const tasks = route(allTasks || [])
  const room = Math.max(1, Math.floor(width))
  if (!tasks.length) return { cells: [], dense: false }
  // the start node, then a leg and a node for each task
  const fits = (legs) => 1 + legs.reduce((a, l) => a + l + 1, 0) <= room
  for (let unit = MAX_UNIT; unit >= 1; unit--) {
    const legs = tasks.map((t) => Math.max(2, weight(t) * unit))
    if (fits(legs)) return { cells: layout(tasks, legs, finished), dense: false }
  }
  const ones = tasks.map(() => 1)
  if (fits(ones)) return { cells: layout(tasks, ones, finished), dense: false }
  return { cells: dense(tasks, room, finished), dense: true }
}

// Another chat's route in the pane: a node and a leg per task, or a glyph per task past maxTasks
export function miniRoute(goal, maxTasks = 12) {
  const tasks = route(goal.tasks || [])
  if (!tasks.length) return { cells: [], dense: false }
  const finished = goal.status === 'met'
  if (tasks.length > maxTasks) return { cells: dense(tasks, tasks.length, finished), dense: true }
  return { cells: layout(tasks, tasks.map(() => 1), finished), dense: false }
}

// Merge neighbouring cells that take the same colour into runs { text, color }, so a
// tick of drawing is a few Text elements, not one per cell. colorOf(cell) → string | null.
export function runs(cells, colorOf) {
  const out = []
  for (const c of cells) {
    const color = colorOf(c)
    const last = out[out.length - 1]
    if (last && last.color === color) last.text += c.ch
    else out.push({ text: c.ch, color })
  }
  return out
}

